-- =============================================================================
-- Seed: Price Types + Product Prices
--
-- Price Types:
--   PT-01  Precio Base       (precio de lista estándar)
--   PT-02  Precio Mayor      (para clientes con volumen)
--   PT-03  Precio Especial   (para clientes con contrato)
--
-- Product Prices: todos los 25 productos (e01..e19) con los 3 tipos
-- Base = precio base (sobre purchase_price del producto)
-- Mayor = precio base * 0.90 (10% descuento)
-- Especial = precio base * 0.82 (18% descuento)
-- profit_margin = NULL (se calcula desde el frontend)
-- =============================================================================

SET FOREIGN_KEY_CHECKS = 0;
DELETE FROM product_prices;
DELETE FROM price_types;
SET FOREIGN_KEY_CHECKS = 1;

-- =============================================================================
-- PRICE TYPES
-- =============================================================================
INSERT INTO price_types (id, name, description, active, created_at, updated_at)
VALUES
    (UNHEX('fa000000000000000000000000000001'), 'Precio Base',     'Precio de lista estándar para todos los clientes',          TRUE, NOW(), NOW()),
    (UNHEX('fa000000000000000000000000000002'), 'Precio Mayor',    'Precio para clientes con volumen de compra alto',           TRUE, NOW(), NOW()),
    (UNHEX('fa000000000000000000000000000003'), 'Precio Especial', 'Precio preferencial para clientes con contrato vigente',    TRUE, NOW(), NOW());

